"use client";

import React, { useState } from 'react';
import { ArrowRight, Search, Menu, Loader2, CheckCircle2, AlertCircle, TrendingDown, TrendingUp, Minus } from 'lucide-react';

export default function Home() {
  const [url, setUrl] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [result, setResult] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleAnalyze = async () => {
    if (!url.trim()) return;

    setIsAnalyzing(true);
    setError(null);
    setResult(null);

    try {
      const response = await fetch('/api/v1/verdict/evaluate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ search_query: url }),
      });

      if (!response.ok) {
        throw new Error('Failed to analyze product. Please try again.');
      }

      const data = await response.json();
      setResult(data);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const getVerdictColor = (verdict: string) => {
    switch (verdict) {
      case 'BUY': return 'bg-green-500 text-white';
      case 'WAIT': return 'bg-yellow-500 text-black';
      case 'AVOID': return 'bg-red-500 text-white';
      default: return 'bg-zinc-800 text-white';
    }
  };

  const isExpanded = isAnalyzing || result || error;

  return (
    <div 
      className="relative w-full min-h-screen flex flex-col font-sans text-zinc-900 overflow-hidden"
      style={{ background: 'linear-gradient(to bottom, #DCEBFA 0%, #E8F2FC 40%, #FFFFFF 100%)' }}
    >
      {/* Subtle Architectural Grid Overlay */}
      <div 
        className="absolute inset-0 z-0 pointer-events-none opacity-40"
        style={{ 
          backgroundImage: 'linear-gradient(rgba(0, 0, 0, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(0, 0, 0, 0.05) 1px, transparent 1px)',
          backgroundSize: '40px 40px'
        }}
      />

      {/* Top Nav */}
      <nav className="w-full p-8 flex justify-between items-center z-40 relative shrink-0">
        <div className="text-[12px] font-bold tracking-widest uppercase">VERDICT Sys.02</div>
        <div className="hidden md:flex gap-10 text-[10px] tracking-[0.3em] uppercase text-zinc-500 font-semibold">
          <span className="hover:text-black cursor-pointer transition-colors">Technology</span>
          <span className="hover:text-black cursor-pointer transition-colors">Methodology</span>
        </div>
        <button className="w-10 h-10 bg-black rounded-full flex items-center justify-center text-white hover:scale-105 transition-transform shadow-lg">
          <Menu size={16} />
        </button>
      </nav>

      {/* Hero Section - Scaled and Animated based on state */}
      <div className={`w-full flex flex-col items-center transition-all duration-1000 ease-in-out ${isExpanded ? 'h-[300px] shrink-0' : 'flex-1 justify-center -mt-12'}`}>
        {/* BULLETPROOF 3D OVERLAP */}
        <main 
          className="w-full relative z-10 transition-transform duration-1000 ease-in-out"
          style={{ 
            display: 'grid', 
            placeItems: 'center',
            transform: isExpanded ? 'scale(0.4) translateY(-30%)' : 'scale(1) translateY(0)'
          }}
        >
          {/* The Giant Text (Background Layer) */}
          <h1 
            className="z-10 font-black tracking-tighter whitespace-nowrap pointer-events-none select-none transition-all duration-1000"
            style={{ 
              gridArea: '1 / 1', 
              fontSize: 'clamp(120px, 22vw, 360px)', 
              color: '#FF4D15', 
              lineHeight: 1,
              letterSpacing: '-0.05em'
            }}
          >
            VERDICT
          </h1>

          {/* The Physical Object (Middle Layer) */}
          <img 
            src="/headphones-cutout.png" 
            alt="Product Visual" 
            className="z-20 object-contain pointer-events-none drop-shadow-2xl transition-transform duration-700 hover:scale-105"
            style={{ 
              gridArea: '1 / 1', 
              width: 'clamp(300px, 45vw, 600px)'
            }}
          />

          {/* The Weaving Text (Foreground Layer, Clipped) */}
          <h1 
            className="z-30 font-black tracking-tighter whitespace-nowrap pointer-events-none select-none transition-all duration-1000"
            style={{ 
              gridArea: '1 / 1', 
              fontSize: 'clamp(120px, 22vw, 360px)', 
              color: '#FF4D15', 
              lineHeight: 1,
              letterSpacing: '-0.05em',
              clipPath: 'polygon(0 0, 48% 0, 48% 100%, 0 100%)'
            }}
          >
            VERDICT
          </h1>
        </main>
      </div>

      {/* Bottom Search Dock - Moves up when expanded */}
      <div className={`relative z-30 w-full max-w-3xl mx-auto px-6 flex flex-col items-center transition-all duration-1000 ease-in-out ${isExpanded ? 'pb-4' : 'pb-12'}`}>
        {/* Trust Pill */}
        <div className={`bg-white/90 backdrop-blur-md px-4 py-1.5 rounded-full shadow-sm border border-zinc-200 flex items-center gap-2 transition-all duration-1000 ${isExpanded ? 'opacity-0 h-0 mb-0 overflow-hidden' : 'opacity-100 h-auto mb-8'}`}>
          <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
          <span className="text-[10px] font-bold tracking-widest text-green-700">98.4% CONFIDENCE</span>
        </div>

        {/* Search Input */}
        <div className={`w-full bg-white rounded-2xl p-2.5 border flex items-center gap-3 relative transition-all duration-500 ${isExpanded ? 'shadow-md border-zinc-200' : 'shadow-2xl border-zinc-200 hover:shadow-3xl'}`}>
          <div className="pl-4 text-zinc-400"><Search size={22} /></div>
          <input 
            type="text" 
            placeholder="Paste Amazon or Flipkart URL to analyze..." 
            value={url}
            onChange={(e) => setUrl(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAnalyze()}
            className="flex-1 bg-transparent border-none outline-none text-zinc-800 placeholder:text-zinc-400 font-medium py-3 text-sm md:text-base"
          />
          <button 
            onClick={handleAnalyze}
            disabled={isAnalyzing}
            className="bg-black hover:bg-[#FF4D15] text-white px-8 py-3.5 rounded-xl font-bold uppercase text-[11px] tracking-widest transition-colors flex items-center gap-2 group shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isAnalyzing ? (
              <><Loader2 size={14} className="animate-spin" /> Analyzing</>
            ) : (
              <>Analyze <ArrowRight size={14} className="group-hover:translate-x-1 transition-transform" /></>
            )}
          </button>
        </div>
      </div>

      {/* Dynamic Results Dashboard */}
      <div className={`w-full max-w-5xl mx-auto px-6 transition-all duration-1000 ease-in-out flex-1 flex flex-col ${isExpanded ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-20 pointer-events-none h-0 overflow-hidden'}`}>

        {/* Error State */}
        {error && (
          <div className="w-full bg-red-50 border border-red-200 rounded-2xl p-6 text-red-700 flex items-start gap-4 mb-8">
            <AlertCircle className="shrink-0 mt-1" />
            <div>
              <h3 className="font-bold mb-1">Analysis Failed</h3>
              <p className="text-sm opacity-80">{error}</p>
            </div>
          </div>
        )}

        {/* Loading State */}
        {isAnalyzing && !error && (
          <div className="w-full h-full flex flex-col items-center justify-center py-20 text-zinc-400 gap-6">
            <Loader2 size={40} className="animate-spin text-[#FF4D15]" />
            <div className="flex flex-col items-center gap-2">
              <h3 className="text-zinc-800 font-bold tracking-tight text-xl">Extracting Intelligence...</h3>
              <p className="text-sm">Crawling reviews, comparing historical prices, and running sentiment analysis.</p>
            </div>
          </div>
        )}

        {/* Success Results State */}
        {result && !isAnalyzing && !error && (
          <div className="w-full pb-20 animate-in fade-in slide-in-from-bottom-8 duration-700">
            {/* Header / Verdict */}
            <div className="flex flex-col md:flex-row gap-6 items-start md:items-end justify-between mb-12">
              <div>
                <div className="flex items-center gap-3 mb-4">
                  <div className={`px-4 py-1.5 rounded-full text-xs font-bold tracking-widest ${getVerdictColor(result.verdict)}`}>
                    VERDICT: {result.verdict}
                  </div>
                  <div className="text-sm font-semibold text-zinc-500">
                    {result.confidence_score}% CONFIDENCE
                  </div>
                </div>
                <h2 className="text-3xl md:text-4xl font-bold tracking-tight text-zinc-900 leading-tight max-w-2xl">
                  {result.executive_summary}
                </h2>
              </div>
            </div>

            {/* Grid Layout for details */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              {/* Pros */}
              <div className="bg-white rounded-3xl p-8 border border-zinc-100 shadow-sm">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-8 h-8 rounded-full bg-green-100 flex items-center justify-center text-green-600">
                    <CheckCircle2 size={16} />
                  </div>
                  <h3 className="font-bold tracking-wide uppercase text-sm">The Good</h3>
                </div>
                <ul className="space-y-4">
                  {result.pros_recap.map((pro: string, idx: number) => (
                    <li key={idx} className="flex items-start gap-3 text-sm text-zinc-600">
                      <div className="w-1.5 h-1.5 rounded-full bg-green-500 mt-1.5 shrink-0" />
                      {pro}
                    </li>
                  ))}
                </ul>
              </div>

              {/* Cons */}
              <div className="bg-white rounded-3xl p-8 border border-zinc-100 shadow-sm">
                <div className="flex items-center gap-3 mb-6">
                  <div className="w-8 h-8 rounded-full bg-red-100 flex items-center justify-center text-red-600">
                    <Minus size={16} />
                  </div>
                  <h3 className="font-bold tracking-wide uppercase text-sm">The Bad</h3>
                </div>
                <ul className="space-y-4">
                  {result.cons_recap.map((con: string, idx: number) => (
                    <li key={idx} className="flex items-start gap-3 text-sm text-zinc-600">
                      <div className="w-1.5 h-1.5 rounded-full bg-red-500 mt-1.5 shrink-0" />
                      {con}
                    </li>
                  ))}
                </ul>
              </div>

              {/* Price Trend & Auth */}
              <div className="flex flex-col gap-6">
                <div className="bg-zinc-900 text-white rounded-3xl p-8 shadow-xl">
                  <div className="flex items-center gap-3 mb-4 opacity-80">
                    <TrendingDown size={16} />
                    <h3 className="font-bold tracking-wide uppercase text-xs">Price Trend</h3>
                  </div>
                  <p className="text-sm leading-relaxed text-zinc-300">
                    {result.price_trend_summary}
                  </p>
                </div>

                <div className="bg-white rounded-3xl p-8 border border-zinc-100 shadow-sm flex-1">
                  <div className="flex items-center gap-3 mb-4 text-zinc-400">
                    <AlertCircle size={16} />
                    <h3 className="font-bold tracking-wide uppercase text-xs text-zinc-900">Review Authenticity</h3>
                  </div>
                  <p className="text-sm leading-relaxed text-zinc-600">
                    {result.review_authenticity_summary}
                  </p>
                </div>
              </div>
            </div>

            {/* Supporting Evidence */}
            <div className="bg-white rounded-3xl p-8 border border-zinc-100 shadow-sm mb-12">
               <h3 className="font-bold tracking-wide uppercase text-sm mb-6 text-zinc-900">Deep Dive</h3>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                 {result.supporting_evidence.map((evidence: string, idx: number) => (
                    <p key={idx} className="text-sm text-zinc-600 leading-relaxed">
                      {evidence}
                    </p>
                 ))}
               </div>
            </div>

          </div>
        )}
      </div>

    </div>
  );
}
